$3250$

$3250$ m

$3250/1000=3.25$

Multiply by 1000 from kilometers to meters.$mw$),
(842,1598,$mw$9694A439B7B98E35DEADD4465557F482FEF93426E8C9816E45205DFFB13E2681$mw$,$mw$d5df56e32b8ddd800b3d5f13c2666326$mw$,$mw$$mw$,$mw${"Id":1598,"StageId":1,"CategoryId":82,"Points":10,"TitleAr":"ما طول 18 سنتيمتراً بالمليمتر؟","TitleEn":"How many millimeters are in 18 centimeters?","QuestionTextAr":"ما طول 18 سنتيمتراً بالمليمتر؟","QuestionTextEn":"How many millimeters are in 18 centimeters?","DetailedSolutionAr":"القانون المستخدم: 1 سنتيمتر = 10 مليمترات، لذا نحول من السنتيمترات إلى المليمترات بضرب الطول في 10. عندنا 18 سم، فنحسب 18 × 10 = 180 مم. التحقق: 180 ÷ 10 = 18 سم، لذلك التحويل متسق.","DetailedSolutionEn":"Rule used: One centimetre equals 10 millimetres. Convert centimetres to millimetres by multiplying by 10. For 18 cm, calculate 18 × 10 = 180 mm. Check the inverse conversion: 180 ÷ 10 = 18 cm.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6381,"Order":1,"LatexCode":"18","IsCorrect":false},{"Id":6382,"Order":2,"LatexCode":"1800","IsCorrect":false},{"Id":6383,"Order":3,"LatexCode":"180","IsCorrect":true},{"Id":6384,"Order":4,"LatexCode":"108","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"كم ملليمتراً في سنتيمتر واحد؟","En":"How many millimeters are in one centimeter?"},{"Ar":"اضرب الطول بالسنتيمتر في عامل التحويل.","En":"Multiply the centimeter length by the conversion factor."}],"Title":{"Ar":"ما طول 18 سنتيمتراً بالمليمتر؟","En":"How many millimeters are in 18 centimeters?"},"Points":10,"Options":[{"LatexCode":"18","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"18 يهمل التحويل.","En":"Eighteen omits the conversion."}},{"LatexCode":"1800","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1800 يستعمل عامل 100 بدلاً من عشرة.","En":"1800 uses a factor of 100 instead of ten."}},{"LatexCode":"180","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"108","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"108 لا يساوي 18 مضروباً في 10.","En":"108 is not eighteen times ten."}}],"StageId":1,"Question":{"Ar":"ما طول 18 سنتيمتراً بالمليمتر؟","En":"How many millimeters are in 18 centimeters?"},"Solution":{"Idea":{"Ar":"السنتيمتر يساوي عشرة ملليمترات.","En":"One centimeter equals ten millimeters."},"Unit":{"Ar":"ملليمتر","En":"mm"},"Steps":[{"Ar":"كل سنتيمتر يحتوي عشرة ملليمترات.","En":"Each centimeter contains ten millimeters."},{"Ar":"$18\\cdot10$","En":"$18\\cdot10$"},{"Ar":"نضرب عدد السنتيمترات في عشرة.","En":"Multiply the centimeter count by ten."}],"Result":{"Ar":"$180$","En":"$180$"},"CommonError":{"Ar":"لا تقسم على 10 عند الانتقال إلى الوحدة الأصغر.","En":"Do not divide by ten when converting to the smaller unit."},"FormulaLatex":"1\\,\\mathrm{cm}=10\\,\\mathrm{mm}","Substitution":{"Ar":"$180$","En":"$180$"},"Verification":{"Ar":"$180/10=18$","En":"$180/10=18$"}},"TrackIds":[4],"CategoryId":82,"PrimarySkillId":323,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"كم ملليمتراً في سنتيمتر واحد؟","En":"How many millimeters are in one centimeter?"},{"Ar":"اضرب الطول بالسنتيمتر في عامل التحويل.","En":"Multiply the centimeter length by the conversion factor."}],"Solution":{"Idea":{"Ar":"السنتيمتر يساوي عشرة ملليمترات.","En":"One centimeter equals ten millimeters."},"Unit":{"Ar":"ملليمتر","En":"mm"},"Steps":[{"Ar":"كل سنتيمتر يحتوي عشرة ملليمترات.","En":"Each centimeter contains ten millimeters."},{"Ar":"$18\\cdot10$","En":"$18\\cdot10$"},{"Ar":"نضرب عدد السنتيمترات في عشرة.","En":"Multiply the centimeter count by ten."}],"Result":{"Ar":"$180$","En":"$180$"},"CommonError":{"Ar":"لا تقسم على 10 عند الانتقال إلى الوحدة الأصغر.","En":"Do not divide by ten when converting to the smaller unit."},"FormulaLatex":"1\\,\\mathrm{cm}=10\\,\\mathrm{mm}","Substitution":{"Ar":"$180$","En":"$180$"},"Verification":{"Ar":"$180/10=18$","En":"$180/10=18$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"18 يهمل التحويل.","En":"Eighteen omits the conversion."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"1800 يستعمل عامل 100 بدلاً من عشرة.","En":"1800 uses a factor of 100 instead of ten."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"108 لا يساوي 18 مضروباً في 10.","En":"108 is not eighteen times ten."},"Order":4}]}$mw$,$mw$السنتيمتر يساوي عشرة ملليمترات.

$1\,\mathrm{cm}=10\,\mathrm{mm}$

